import java.lang.management.ManagementFactory;
import java.lang.management.MemoryMXBean;
import java.lang.management.MemoryPoolMXBean;
import java.lang.management.MemoryUsage;
import java.util.Set;
import java.util.stream.Collectors;

public class Main {
    private static final String STATIC_LITERAL = "jvm";
    private final byte[] instanceField = new byte[16];

    static int currentStackDepthAfter(int n) {
        if (n == 0) return Thread.currentThread().getStackTrace().length;
        return currentStackDepthAfter(n - 1);
    }

    public static void main(String[] args) {
        Main demo = new Main();
        Object heapObject = new Object();
        String localString = new String("jvm");

        MemoryMXBean memory = ManagementFactory.getMemoryMXBean();
        MemoryUsage heap = memory.getHeapMemoryUsage();
        MemoryUsage nonHeap = memory.getNonHeapMemoryUsage();
        Set<String> pools = ManagementFactory.getMemoryPoolMXBeans().stream()
            .map(MemoryPoolMXBean::getName)
            .collect(Collectors.toSet());

        boolean hasMetaspace = pools.stream().anyMatch(name -> name.contains("Metaspace"));
        boolean hasCodeCache = pools.stream().anyMatch(name -> name.contains("CodeHeap") || name.contains("Code Cache"));
        boolean compileTimeInterned = "jvm" == "j" + "vm";
        boolean newStringIsDifferentObject = localString != STATIC_LITERAL;
        int stackDepth = currentStackDepthAfter(3);
        int threadCount = ManagementFactory.getThreadMXBean().getThreadCount();

        System.out.println("heap used: " + heap.getUsed());
        System.out.println("non-heap used: " + nonHeap.getUsed());
        System.out.println("memory pools: " + pools);
        System.out.println("stack depth sample: " + stackDepth + ", threads: " + threadCount);
        System.out.println("literal interned: " + compileTimeInterned + ", new String differs: " + newStringIsDifferentObject);

        assert heap.getUsed() >= 0;
        assert nonHeap.getUsed() >= 0;
        assert hasMetaspace;
        assert hasCodeCache;
        assert compileTimeInterned;
        assert newStringIsDifferentObject;
        assert stackDepth > 0;
        assert threadCount > 0;
        assert demo.instanceField.length == 16;
        assert heapObject != null;
    }
}
